def main(inp):
    import re
    from collections import Counter
    files = inp.get('files', {})
    answers = {}
    for name in ['solve', 'solve_copy1', 'solve_copy2']:
        txt = files.get(name + '.txt', '')
        m = re.findall(r'<answer>\s*([A-E])\s*</answer>', txt)
        if m:
            answers[name] = m[-1]
    if len(answers) < 2:
        return {'verdict': 'proceed', 'reason': 'ok'}
    votes = Counter(answers.values())
    top, count = votes.most_common(1)[0]
    if count < 2:
        return {'verdict': 'proceed', 'reason': 'no majority'}
    chosen = files.get('solve_choose.txt', '')
    first = chosen.strip().split()[0] if chosen.strip() else ''
    if first not in answers:
        return {'verdict': 'reloop', 'reason': 'Your response must start with exactly one of: solve, solve_copy1, solve_copy2. No other text before it.'}
    if answers.get(first, '') != top:
        return {'verdict': 'reloop', 'reason': 'Majority answer is ' + top + ' (' + str(count) + '/3 solvers agree). You selected ' + first + ' which answered ' + answers[first] + '. You MUST select a step whose answer is ' + top + '.'}
    return {'verdict': 'proceed', 'reason': 'ok'}

